import java.util.*;

public class Main {
    static final int MOD = 1000000007;

    static int add(int a, int b) {
        a += b;
        if (a >= MOD) a -= MOD;
        return a;
    }

    static int mult(int a, int b) {
        long t = 1L * a * b;
        if (t >= MOD) t %= MOD;
        return (int) t;
    }

    static class Matrix {
        int[][] dat;
        int N, M;

        Matrix(int n, int m) {
            this.N = n;
            this.M = m;
            dat = new int[N][M];
        }

        void init() {
            for (int i = 0; i < N; i++)
                Arrays.fill(dat[i], 0);
        }

        void iden() {
            init();
            int size = Math.min(N, M);
            for (int i = 0; i < size; i++) {
                dat[i][i] = 1;
            }
        }

        Matrix trans() {
            Matrix out = new Matrix(M, N);
            for (int i = 0; i < M; i++)
                for (int j = 0; j < N; j++)
                    out.dat[i][j] = dat[j][i];
            return out;
        }

        int[] getRow(int x) {
            return dat[x];
        }

        int[] getCol(int x) {
            int[] col = new int[N];
            for (int i = 0; i < N; i++) {
                col[i] = dat[i][x];
            }
            return col;
        }

        Matrix add(Matrix a) {
            Matrix out = new Matrix(N, M);
            out.init();
            for (int i = 0; i < N; i++)
                for (int j = 0; j < M; j++)
                    out.dat[i][j] = add(this.dat[i][j], a.dat[i][j]);
            return out;
        }

        Matrix multiplyByInt(int x) {
            Matrix out = new Matrix(N, M);
            for (int i = 0; i < N; i++)
                for (int j = 0; j < M; j++)
                    out.dat[i][j] = mult(this.dat[i][j], x);
            return out;
        }

        static Matrix multiply(Matrix a, Matrix b) {
            int n = a.N;
            int m = a.M;
            int p = b.M;
            Matrix out = new Matrix(n, p);
            out.init();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (a.dat[i][j] != 0) {
                        int[] bRow = b.dat[j];
                        int val = a.dat[i][j];
                        for (int k = 0; k < p; k++) {
                            if (bRow[k] != 0) {
                                out.dat[i][k] = add(out.dat[i][k], mult(val, bRow[k]));
                            }
                        }
                    }
                }
            }
            return out;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long n = sc.nextLong();
        int K = sc.nextInt();

        // Initialize matrices A, S, P
        int maxPower = 64; // enough for the loop
        Matrix[][][] A = new Matrix[maxPower + 1][K][1];
        Matrix[][][] S = new Matrix[maxPower + 1][K][1];
        Matrix[][][] P = new Matrix[maxPower + 1][K][1];

        // Initialize A[0][i]
        for (int i = 0; i < K; i++) {
            A[0][i][0] = new Matrix(K, K);
            A[0][i][0].iden();
            // Set diagonal to 1
            for (int j = 0; j < K; j++) {
                A[0][i][0].dat[j][j] = 1;
            }
        }

        long len = K;
        int idx = 1;
        while (len <= n) {
            for (int i = 0; i < K; i++) {
                A[idx][i][0] = new Matrix(K, K);
                A[idx][i][0].init();
            }

            // Compute S[i-1][j]
            for (int j = 0; j < K; j++) {
                S[idx - 1][j][0] = A[idx - 1][j][0];
                for (int jj = j + 1; jj < K; jj++) {
                    S[idx - 1][j][0] = Matrix.multiply(S[idx - 1][j][0], A[idx - 1][jj][0]);
                }
            }

            // Compute P[i-1][j]
            for (int j = 0; j < K; j++) {
                P[idx - 1][j][0] = A[idx - 1][j][0];
                for (int jj = j - 1; jj >= 0; jj--) {
                    P[idx - 1][j][0] = Matrix.multiply(P[idx - 1][j][0], A[idx - 1][jj][0]);
                }
            }

            // Compute A[i][j]
            A[idx][0][0] = S[idx - 1][0][0];
            for (int j = 1; j < K; j++) {
                A[idx][j][0] = Matrix.multiply(S[idx - 1][j][0], P[idx - 1][j - 1][0]);
            }

            len *= K;
            idx++;
        }

        // Convert n to base K
        List<Integer> digit = new ArrayList<>();
        long tempN = n;
        while (tempN > 0) {
            digit.add((int) (tempN % K));
            tempN /= K;
        }

        // Initialize ans as identity matrix
        Matrix ans = new Matrix(K, K);
        ans.iden();

        int s = 0;
        for (int i = digit.size() - 1; i >= 0; i--) {
            int d = digit.get(i);
            for (int j = 0; j < d; j++) {
                ans = Matrix.multiply(ans, A[i][(j + s) % K][0]);
            }
            s = (s + d) % K;
        }

        int res = 1;
        for (int i = 0; i < K; i++) {
            res = add(res, ans.dat[i][K - 1]);
        }

        System.out.println(res);
        sc.close();
    }
}
